-- Audit trail of every scoring rule that fired for a hearing test request.

CREATE TABLE hearing_test_request_grade_rule (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    hearing_test_request_grade_id UUID NOT NULL
        REFERENCES hearing_test_request_grade(id) ON DELETE CASCADE,
    rule_id VARCHAR(40) NOT NULL,
    axis VARCHAR(20) NOT NULL DEFAULT ''
        CHECK (axis IN ('appropriateness', 'urgency', 'completeness', 'priority', '')),
    category VARCHAR(50) NOT NULL DEFAULT '',
    description VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX index_hearing_test_request_grade_rule_grade_id
    ON hearing_test_request_grade_rule(hearing_test_request_grade_id);

