-- Safety-critical flags for a hearing test request, independent of the axes.

CREATE TABLE hearing_test_request_grade_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    hearing_test_request_grade_id UUID NOT NULL
        REFERENCES hearing_test_request_grade(id) ON DELETE CASCADE,
    flag_id VARCHAR(50) NOT NULL,
    category VARCHAR(50) NOT NULL DEFAULT ''
        CHECK (category IN (
            'sudden-sensorineural-hearing-loss-urgent',
            'unilateral-symptoms-red-flag',
            'ear-discharge',
            'missing-indication',
            'missing-clinical-question',
            'other',
            ''
        )),
    priority VARCHAR(10) NOT NULL DEFAULT ''
        CHECK (priority IN ('low', 'medium', 'high', '')),
    description VARCHAR(500) NOT NULL DEFAULT '',
    suggested_action VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX index_hearing_test_request_grade_flag_grade_id
    ON hearing_test_request_grade_flag(hearing_test_request_grade_id);

CREATE TRIGGER trigger_hearing_test_request_grade_flag_updated_at
    BEFORE UPDATE ON hearing_test_request_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE hearing_test_request_grade_flag IS
