    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN hearing_test_request_grade_flag.hearing_test_request_grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN hearing_test_request_grade_flag.flag_id IS
    'Stable flag identifier (e.g. F-SUDDEN-SNHL-001).';
COMMENT ON COLUMN hearing_test_request_grade_flag.category IS
    'Flag category.';
COMMENT ON COLUMN hearing_test_request_grade_flag.priority IS
    'Priority: low, medium, high.';
COMMENT ON COLUMN hearing_test_request_grade_flag.description IS
